/// INPA screen tree for a module code (CFGDAT script), or None if not extracted.
/// Case-insensitive (catalog codes vary in case across CFGDAT files).
pub fn get(code: &str) -> Option<&'static SgModule> {
    MODULES.iter().find(|m| m.code.eq_ignore_ascii_case(code))
}

/// INPA live-measurement screens (curated, grouped, mirror-INPA job calls) for
/// a module code, or empty if none extracted. Case-insensitive.
pub fn meas_screens(code: &str) -> &'static [MeasScreen] {
    get(code).map(|m| m.meas).unwrap_or(&[])
}
